// Writes lib/articles/index.js: one static import per article file, so the
// pages can list every article without a dynamic require.
import { readdirSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dir = join(root, 'lib', 'articles');

export function buildArticleIndex() {
  const files = readdirSync(dir)
    .filter((f) => f.endsWith('.js') && f !== 'index.js')
    .sort();
  const lines = [
    '// Generated by scripts/build-article-index.mjs: do not edit by hand.',
    '// To publish an article, add its file to lib/articles/ and run the build.',
    ...files.map((f, i) => `import a${i} from './${f}';`),
    '',
    `export const articles = [${files.map((_, i) => `a${i}`).join(', ')}];`,
    '',
  ];
  writeFileSync(join(dir, 'index.js'), lines.join('\n'));
  return files.length;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  console.log(`lib/articles/index.js: ${buildArticleIndex()} articles`);
}
